<template>
 <SetupDialog ref="shell" :model-value="store.open&&!blocked&&!store.panel" title="إعداد شركتي خطوة بخطوة" :eyebrow="snapshot?.data.company.name||'بداية مرتبة لعملك'" :description="current.title" :busy="store.saving" @close="close">
  <template v-if="snapshot" #progress><div class="setup-stepbar"><progress :value="index+1" :max="snapshot.steps.length" aria-label="تقدم إعداد الشركة" /><span>الخطوة {{ index+1 }} من {{ snapshot.steps.length }}</span></div></template>
  <div v-if="store.loading" role="status" class="setup-note">جار تحميل بياناتك…</div>
  <div v-if="store.error" class="setup-error" role="alert">{{ store.error }} <button type="button" class="setup-btn setup-btn-quiet" @click="reload">إعادة تحميل البيانات</button></div>
  <template v-if="snapshot&&!store.loading">
   <div v-if="!current.can_edit" class="setup-note">يمكنك مراجعة الإعداد. التعديل يحتاج مسؤول الشركة.</div>
   <form id="company-compact-form" @submit.prevent="next(false)"><fieldset :disabled="!current.can_edit||store.saving">
    <template v-if="key==='basics'">
     <section class="setup-section"><h3>عرّف نشاطك</h3><p class="setup-help">ستظهر هذه البيانات في فواتيرك. راجع الموجود، وأكمل ما ينقصه فقط.</p><div class="setup-grid">
      <label class="setup-label">اسم الشركة <small>مطلوب</small><input v-model="form.company.name" class="setup-input" name="company-name" required maxlength="255" /></label>
      <label class="setup-label">رقم التواصل <small>مطلوب</small><input v-model="form.company.phone" class="setup-input" type="tel" required maxlength="15" /></label>
      <label class="setup-label setup-wide">عنوان الشركة <small>مطلوب</small><input v-model="form.company.address" class="setup-input" required maxlength="255" /></label>
      <label class="setup-label">البريد الإلكتروني <small>اختياري</small><input v-model="form.company.email" class="setup-input" type="email" /></label>
      <label class="setup-label">اسم المسؤول <small>اختياري</small><input v-model="form.company.owner_name" class="setup-input" maxlength="255" /></label>
     </div><details class="setup-details"><summary>الشعار وروابط التواصل — اختياري</summary><div><button type="button" class="setup-btn" @click="pickLogo">اختيار شعار الشركة</button><img v-if="form.company.logo_url" :src="form.company.logo_url" alt="شعار الشركة الحالي" width="90" height="70" style="object-fit:contain;vertical-align:middle;margin-inline-start:12px" /><div v-for="(social,i) in form.company.social_links" :key="i" class="setup-grid" style="margin-top:12px"><label class="setup-label">اسم وسيلة التواصل<input v-model="social.platform" class="setup-input" maxlength="50" /></label><label class="setup-label">الرابط<input v-model="social.url" type="url" class="setup-input" /></label><button type="button" class="setup-btn setup-btn-quiet" @click="form.company.social_links.splice(i,1)">إزالة الرابط</button></div><button type="button" class="setup-btn setup-btn-quiet" @click="form.company.social_links.push({platform:'',url:''})">إضافة رابط تواصل</button></div></details></section>
     <section class="setup-section"><h3>أين تحتفظ بالبضاعة؟</h3><p class="setup-help">اختر مخزنك الموجود. لن ننقله من فرعه أو ننشئ نسخة أخرى منه.</p><div class="setup-grid"><label class="setup-label">المخزن الرئيسي<select v-model="form.warehouse.id" class="setup-input" @change="chooseWarehouse"><option :value="null">اختر المخزن</option><option v-for="w in snapshot.data.warehouses" :key="w.id" :value="w.id">{{ w.name }}</option></select></label><label v-if="form.warehouse.id" class="setup-label">عنوان المخزن بالتفصيل<input v-model="form.warehouse.location" class="setup-input" required maxlength="255" /></label></div><div v-if="form.warehouse.id" style="margin-top:12px"><button type="button" class="setup-btn" @click="pickWarehouseLocation">تحديد مكان المخزن</button><span class="setup-help" style="margin-inline-start:12px">{{ form.warehouse.location_confirmed?'تم تأكيد موقع المخزن':'يمكن تحديد الموقع الآن أو قبل بدء التوصيل' }}</span></div><button v-else type="button" class="setup-btn" @click="openOption('warehouses')">إضافة مخزن</button><details class="setup-details"><summary>إعدادات الشركة وأماكن العمل</summary><div class="setup-link-grid"><button v-for="option in ['company_extra','branches','warehouses','subscription']" :key="option" type="button" class="setup-btn" @click="openOption(option)">{{ optionTitles[option] }}</button></div></details></section>
    </template>
    <template v-else-if="key==='preferences'">
     <section class="setup-section"><h3>تكلفة الشراء</h3><label class="setup-check"><input v-model="form.auto_update_purchase_price" type="checkbox" /><span>تحديث تكلفة الشراء عند تسجيل مشتريات جديدة</span></label><p class="setup-help">فعّله إذا أردت اعتماد تكلفة الشراء الجديدة تلقائيًا. لن نغيّر اختيارك الحالي أو طريقة حساب المخزون دون حفظك.</p></section>
     <section class="setup-section"><h3>شكل فاتورتك</h3><div class="setup-grid"><div><label class="setup-label">حجم الطباعة<select v-model="form.print_format" class="setup-input"><option v-for="item in printFormats" :key="item.value" :value="item.value">{{ item.title }}</option></select></label><label class="setup-check" style="margin-top:12px"><input v-model="form.show_logo" type="checkbox" />إظهار شعار الشركة</label><label class="setup-label">عبارة أسفل الفاتورة <small>اختياري</small><textarea v-model="form.footer_text" class="setup-input" rows="3" maxlength="500" /></label></div><div class="setup-preview" aria-label="معاينة الفاتورة"><img v-if="form.show_logo&&snapshot.data.company.logo_url" :src="snapshot.data.company.logo_url" alt="الشعار" width="60" height="50" style="object-fit:contain;margin:auto" /><h4>{{ snapshot.data.company.name }}</h4><small>{{ printFormats.find(p=>p.value===form.print_format)?.title }}</small><hr /><p>المنتج · الكمية · السعر</p><p>{{ form.footer_text||'عبارتك ستظهر هنا' }}</p><small>معاينة فقط — لم تُنشأ فاتورة</small></div></div></section>
     <details class="setup-details"><summary>إعدادات إضافية عند الحاجة</summary><div class="setup-link-grid"><button v-for="option in ['permissions','units','conversions','categories','brands','billing','payments','cashboxes']" :key="option" type="button" class="setup-btn" @click="openOption(option)">{{ optionTitles[option] }}</button></div><p class="setup-help">وحدة البيع تُختار لكل منتج. هذه الخيارات لا تفرض وحدة واحدة على منتجاتك.</p></details>
    </template>
    <template v-else-if="key==='store_setup'">
     <div class="setup-note">هذه الصفحة اختيارية. يمكنك البدء بالمنتجات والفواتير وتأجيل تجهيز المتجر.</div>
     <section class="setup-section"><h3>تجهيز الطلبات</h3><div class="setup-grid"><label class="setup-label">مخزن تجهيز الطلبات<select v-model="form.warehouse_id" class="setup-input" required><option :value="null">اختر المخزن</option><option v-for="w in snapshot.data.warehouses" :key="w.id" :value="w.id">{{ w.name }}</option></select></label><label class="setup-label">هاتف التواصل لتجهيز الطلبات<input v-model="form.phone" type="tel" class="setup-input" required maxlength="30" /></label><label class="setup-label">المدينة<input v-model="form.city" class="setup-input" required maxlength="100" /></label><label class="setup-label">المحافظة<select v-model="form.governorate_code" class="setup-input" required><option value="">اختر المحافظة</option><option v-for="g in governorates" :key="g.id" :value="g.id">{{ g.name }}</option></select></label></div><button type="button" class="setup-btn setup-btn-quiet" @click="openOption('seller_identity')">بيانات البائع ومسؤول تسليم الشحنات والضريبة</button></section>
     <section class="setup-section"><h3>كيف ستوصل الطلبات؟</h3><label class="setup-check"><input v-model="form.local_enabled" type="checkbox" />أتولى توصيل الطلبات بنفسي</label><div v-if="form.local_enabled"><p class="setup-help">حدد نطاقك القريب ورسم التوصيل. خارج النطاق يُستخدم ناقل متاح، وإلا يستمر توصيلك وفق السياسة الحالية.</p><div class="setup-grid"><label class="setup-label">النطاق بالكيلومترات<input v-model="form.radius_km" class="setup-input" type="number" min="0.001" max="20000" step="any" required /></label><label class="setup-label">رسم التوصيل بالجنيه<input v-model="form.fee" class="setup-input" type="number" min="0" step="0.01" required /></label><label class="setup-label">توصيل مجاني بدءًا من <small>اختياري — قيمة مشتريات هذا البائع بالجنيه</small><input v-model="form.free_above" class="setup-input" type="number" min="0" step="0.01" /></label></div><button type="button" class="setup-btn setup-btn-quiet" @click="pickDeliveryLocation">تحديد موقع مخزن الطلبات</button></div></section>
     <details class="setup-details"><summary>استلام مستحقاتك — عند الحاجة</summary><div><p class="setup-help">تحتاج هذه البيانات إذا كانت المنصة تستلم الأموال نيابةً عنك. تبقى بياناتك المعتمدة كما هي؛ التغيير يُرسل للمراجعة.</p><div class="setup-grid"><label class="setup-label">طريقة الاستلام<select v-model="form.payout_type" class="setup-input"><option :value="null">لا تغيير الآن</option><option value="bank">حساب بنكي</option><option value="e_wallet">محفظة إلكترونية</option></select></label><template v-if="form.payout_type"><label class="setup-label">اسم صاحب الحساب أو المحفظة<input v-model="form.payout_account_holder" class="setup-input" required /></label><label class="setup-label">رقم الحساب أو المحفظة<input v-model="form.payout_account_number" class="setup-input" required autocomplete="off" /></label><label v-if="form.payout_type==='bank'" class="setup-label">رقم الحساب الدولي IBAN <small>إن وجد</small><input v-model="form.payout_iban" class="setup-input" autocomplete="off" /></label></template></div></div></details><button type="button" class="setup-btn setup-btn-quiet" @click="openOption('policies')">سياسات البيع والمرتجعات والعمولات</button>
    </template>
    <template v-else-if="key==='summary'">
     <section class="setup-section"><h3>خطوتك التالية واضحة</h3><div class="setup-result"><strong :class="{'setup-success':snapshot.basic_ready}">{{ snapshot.basic_ready?'جاهز للعمل داخل النظام':'العمل داخل النظام يحتاج استكمالًا' }}</strong><p class="setup-help">{{ snapshot.basic_ready?'يمكنك إدارة عملك باستخدام الإعدادات المحفوظة.':'راجع التفاصيل لتعرف الإعداد الناقص وتفتحه مباشرة.' }}</p></div><div class="setup-result"><strong :class="{'setup-success':snapshot.store_ready}">{{ snapshot.store_ready?'جاهز للبيع في المتجر':'البيع في المتجر غير جاهز بعد' }}</strong><p class="setup-help">جاهزية المتجر مستقلة عن الفواتير، وقد تحتاج بيانات أو موافقة من الإدارة.</p></div><details v-if="snapshot.issues.length" class="setup-details"><summary>تفاصيل ما ينقصني ({{ snapshot.issues.length }})</summary><div><ul class="setup-list"><li v-for="(issue,i) in snapshot.issues" :key="i" class="setup-list-row"><span>{{ issue.message }}</span><button type="button" class="setup-btn setup-btn-quiet" @click="resolveIssue(issue)">استكمال</button></li></ul></div></details><details class="setup-details"><summary>ما حُفظ وما أُجّل</summary><div><ul class="setup-list"><li v-for="step in snapshot.steps.filter(s=>s.key!=='summary')" :key="step.key" class="setup-list-row"><span>{{ step.title }}<small style="display:block">{{ snapshot.state.deferred.includes(step.key)?'أُجّلت — البيانات السابقة محفوظة':snapshot.state.reviewed.includes(step.key)?'تمت المراجعة والحفظ':'لم تُراجع بعد' }}</small></span><button type="button" class="setup-btn setup-btn-quiet" @click="go(step.key)">مراجعة</button></li></ul></div></details></section>
     <button v-if="snapshot.product_ready&&user.hasPermission('products.create')" type="button" class="setup-btn setup-btn-primary" @click="finish(true)">إنهاء وإضافة أول منتج</button>
    </template>
   </fieldset></form>
  </template>
  <template #actions><div style="width:100%"><label class="setup-check" style="font-size:12px"><input v-model="hideAgain" type="checkbox" />لا تظهر هذا الدليل تلقائيًا مرة أخرى</label><p class="setup-help" style="margin:0">يمكنك فتحه دائمًا من القائمة أو إعدادات الشركة.</p></div><button v-if="index>0" type="button" class="setup-btn" :disabled="store.saving" @click="previous">السابق</button><span class="setup-grow" /><button v-if="snapshot&&key!=='summary'" type="button" class="setup-btn setup-btn-quiet" :disabled="store.saving||store.loading" @click="skip">{{ key==='store_setup'?'تجهيز المتجر لاحقًا':'تخطي الآن' }}</button><button v-if="snapshot" :type="key==='summary'?'button':'submit'" :form="key==='summary'?undefined:'company-compact-form'" class="setup-btn setup-btn-primary" :disabled="store.saving||store.loading" @click="key==='summary'?finish(false):undefined">{{ store.saving?'جار الحفظ…':key==='summary'?'حفظ وإنهاء':current.can_edit?'حفظ ومتابعة':'متابعة' }}</button></template>
 </SetupDialog>
</template>
<script setup>
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRouter} from 'vue-router'
import {useUserStore} from '@/stores/user'
import {useCompanySetupStore} from '../store/useCompanySetupStore'
import SetupDialog from './SetupDialog.vue'
import {optionTitles} from '../config/setupOptions'
import api from '../api/setupApi'
const props=defineProps({blocked:Boolean})
const store=useCompanySetupStore(),user=useUserStore(),router=useRouter(),shell=ref()
const snapshot=computed(()=>store.snapshot),key=ref('basics'),form=ref({}),baseline=ref(''),hideAgain=ref(false),governorates=ref([])
const current=computed(()=>snapshot.value?.steps.find(s=>s.key===key.value)||{title:'',can_edit:false}),index=computed(()=>Math.max(0,snapshot.value?.steps.findIndex(s=>s.key===key.value)??0))
const printFormats=[{title:'ورقة A4',value:'standard'},{title:'ورقة A5',value:'a5'},{title:'إيصال 80 مم',value:'thermal'},{title:'إيصال 58 مم',value:'thermal_58'}]
const clone=v=>JSON.parse(JSON.stringify(v))
function fromSnapshot(step){const d=snapshot.value.data,s=d.settings||{},w=d.warehouses.find(w=>w.is_default)||d.warehouses[0];
 if(step==='basics')return {company:{...d.company,social_links:clone(d.company.social_links||[])},warehouse:{id:w?.id||null,location:w?.location||'',latitude:w?.latitude??null,longitude:w?.longitude??null,location_confirmed:!!w?.location_confirmed}}
 if(step==='preferences')return {auto_update_purchase_price:!!s.auto_update_purchase_price,print_format:s.print_settings?.print_format||'standard',show_logo:s.print_settings?.show_logo??true,footer_text:s.print_settings?.footer_text||''}
 if(step==='store_setup'){const p=d.store?.profile||{},a=p.pickup_address||{},local=d.store?.delivery?.settings||{};return {warehouse_id:p.warehouse_id||w?.id||null,phone:a.phone||d.company.phone||'',city:a.city||'',governorate_code:a.governorate_code||'',local_enabled:!!local.enabled,radius_km:local.radius_meters?local.radius_meters/1000:null,fee:(local.fee_minor||0)/100,free_above:local.free_above_minor==null?null:local.free_above_minor/100,payout_type:null,payout_account_holder:'',payout_account_number:'',payout_iban:null}}
 return {}
}
function fill(){if(!snapshot.value)return;const fresh=fromSnapshot(key.value),draft=store.drafts[key.value];form.value=draft?clone(draft.form):fresh;baseline.value=draft?.baseline||JSON.stringify(fresh);nextTick(()=>shell.value?.top())}
const dirty=()=>JSON.stringify(form.value)!==baseline.value
function remember(){store.drafts[key.value]={form:clone(form.value),baseline:baseline.value}}
function go(step){remember();key.value=step;fill();store.error=''}
function previous(){go(snapshot.value.steps[index.value-1].key)}
function openOption(option){remember();store.openPanel(option)}
function chooseWarehouse(){const w=snapshot.value.data.warehouses.find(w=>Number(w.id)===Number(form.value.warehouse.id));if(w)form.value.warehouse={id:w.id,location:w.location||'',latitude:w.latitude??null,longitude:w.longitude??null,location_confirmed:!!w.location_confirmed}}
function pickWarehouseLocation(){remember();store.pickLocation(form.value.warehouse,value=>{Object.assign(form.value.warehouse,value);remember()})}
function pickDeliveryLocation(){const w=snapshot.value.data.warehouses.find(w=>Number(w.id)===Number(form.value.warehouse_id));if(!w){store.error='اختر مخزن تجهيز الطلبات أولًا.';return}remember();store.pickLocation(w,()=>{});store.locationAccept=null;store.panelDraft={...clone(w),saveWarehouse:true}}
function pickLogo(){remember();store.locationAccept=asset=>{form.value.company.logo_id=asset.id;form.value.company.logo_url=asset.url;remember()};store.openPanel('logo')}
function resolveIssue(issue){const map={locations:'locations',inventory:'units',billing:'billing',team:'users',email:'email',whatsapp:'whatsapp',automation:'automation',store:'seller_identity'};if(issue.section==='company')go('basics');else openOption(map[issue.section]||'seller_identity')}
async function next(defer=false){const data=defer||!current.value.can_edit?{}:clone(form.value);if(key.value==='basics'&&!data.warehouse?.id)delete data.warehouse;if(await store.save(key.value,data,defer)){delete store.drafts[key.value];key.value=store.snapshot.state.current_step;fill()}}
async function skip(){if(dirty()&&!window.confirm('هل تريد تخطي الصفحة دون حفظ التعديلات الحالية؟'))return;await next(true)}
async function finish(product){remember();if(Object.values(store.drafts).some(d=>JSON.stringify(d.form)!==d.baseline)&&!window.confirm('توجد تعديلات لم تحفظ في الدليل. هل تريد الإنهاء دون حفظها؟'))return;if(!await store.save('summary',{}))return;if(hideAgain.value!==snapshot.value.state.hidden&&!await store.setHidden(hideAgain.value))return;store.open=false;store.drafts={};if(product)router.push('/app/products/create')}
async function close(){remember();if(Object.values(store.drafts).some(d=>JSON.stringify(d.form)!==d.baseline)&&!window.confirm('توجد تعديلات لم تحفظ. إغلاق الدليل لن يحفظها. هل تريد الإغلاق؟'))return;if(snapshot.value&&hideAgain.value!==snapshot.value.state.hidden&&!await store.setHidden(hideAgain.value))return;store.open=false}
async function reload(){if(dirty()&&!window.confirm('هل تريد تحميل البيانات المحفوظة بدل التعديلات الحالية؟'))return;delete store.drafts[key.value];await store.load(user.currentUser?.active_company_id);fill()}
watch(()=>store.open,async open=>{if(!open||!snapshot.value)return;hideAgain.value=!!snapshot.value.state.hidden;key.value=snapshot.value.state.current_step||'basics';fill();const token=sessionStorage.getItem('token')||localStorage.getItem('token')||'session';sessionStorage.setItem('company_setup_seen_'+user.currentUser?.id+'_'+snapshot.value.company_id,token);try{const r=await api.get('/store/public/checkout-config');governorates.value=r.data?.data?.governorates||[]}catch{store.error='تعذر تحميل المحافظات. أعد تحميل البيانات قبل تجهيز المتجر.'}})
watch([()=>user.currentUser?.id,()=>user.currentUser?.active_company_id],async([userId,id])=>{store.reset();if(!id||!user.currentUser?.is_staff_or_admin)return;store.autoPending=true;await store.load(id);store.autoPending=false},{immediate:true})
let timer;onMounted(()=>{timer=setInterval(()=>{const s=snapshot.value;if(props.blocked||!s||store.open||store.panel||s.state.hidden||s.state.finished||document.querySelector('.v-overlay--active'))return;const token=sessionStorage.getItem('token')||localStorage.getItem('token')||'session',seen='company_setup_seen_'+user.currentUser?.id+'_'+s.company_id;if(sessionStorage.getItem(seen)!==token)store.open=true},1000)});onUnmounted(()=>clearInterval(timer))
</script>
